package com.primehr.migration;
import org.junit.jupiter.api.Test; import java.io.*; import java.nio.charset.StandardCharsets; import java.util.Set; import static org.assertj.core.api.Assertions.assertThat;
class SuccessionV48MigrationParityTest {
 @Test void pairedMigrationsHaveMatchingCareerAndCriticalPositionStructures()throws Exception{String p=read("db/migration/postgresql/V48__succession_career_paths_critical_positions.sql").toLowerCase(),s=read("db/migration/sqlserver/V48__succession_career_paths_critical_positions.sql").toLowerCase();Set<String> names=Set.of("succession_career_family","succession_career_family_version","succession_career_path_link","succession_criticality_framework","succession_criticality_framework_version","succession_criticality_criterion","succession_critical_position_designation","succession_criticality_finding","ix_succ_family_effective","ix_succ_path_family","ix_succ_criticality_effective","ix_succ_criterion_framework","ix_succ_designation_target","ix_succ_designation_committee","ix_succ_finding_designation");for(String migration:Set.of(p,s)){assertThat(migration).contains(names.toArray(String[]::new));assertThat(migration).doesNotContain("insert into","delete from","drop table","employee_id bigint not null,employee_no","candidate","readiness_score");}}
 private String read(String path)throws IOException{try(var in=getClass().getClassLoader().getResourceAsStream(path)){if(in==null)throw new IOException(path);return new String(in.readAllBytes(),StandardCharsets.UTF_8);}}
}
